#!/usr/bin/env python3
from pwn import *
import hashlib
import struct

def sha256_padding(message_length):
    padding = b''
    padding += b'\x80'
    padding += b'\x00' * ((56 - (message_length + 1) % 64) % 64)
    padding += struct.pack('>Q', message_length * 8)
    return padding

def int_to_bytes(n, length):
    return n.to_bytes(length, byteorder='big')

def bytes_to_int(b):
    return int.from_bytes(b, byteorder='big')

def sha256_compress(state, block):
    k = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
    ]

    def rotr(x, n):
        return ((x >> n) | (x << (32 - n))) & 0xffffffff

    def ch(x, y, z):
        return (x & y) ^ (~x & z)

    def maj(x, y, z):
        return (x & y) ^ (x & z) ^ (y & z)

    def sigma0(x):
        return rotr(x, 2) ^ rotr(x, 13) ^ rotr(x, 22)

    def sigma1(x):
        return rotr(x, 6) ^ rotr(x, 11) ^ rotr(x, 25)

    def gamma0(x):
        return rotr(x, 7) ^ rotr(x, 18) ^ (x >> 3)

    def gamma1(x):
        return rotr(x, 17) ^ rotr(x, 19) ^ (x >> 10)

    w = []
    for i in range(16):
        w.append(struct.unpack('>I', block[i*4:(i+1)*4])[0])
    for i in range(16, 64):
        w.append((gamma1(w[i-2]) + w[i-7] + gamma0(w[i-15]) + w[i-16]) & 0xffffffff)

    a, b, c, d, e, f, g, h = state

    for i in range(64):
        t1 = (h + sigma1(e) + ch(e, f, g) + k[i] + w[i]) & 0xffffffff
        t2 = (sigma0(a) + maj(a, b, c)) & 0xffffffff
        h = g
        g = f
        f = e
        e = (d + t1) & 0xffffffff
        d = c
        c = b
        b = a
        a = (t1 + t2) & 0xffffffff

    state[0] = (state[0] + a) & 0xffffffff
    state[1] = (state[1] + b) & 0xffffffff
    state[2] = (state[2] + c) & 0xffffffff
    state[3] = (state[3] + d) & 0xffffffff
    state[4] = (state[4] + e) & 0xffffffff
    state[5] = (state[5] + f) & 0xffffffff
    state[6] = (state[6] + g) & 0xffffffff
    state[7] = (state[7] + h) & 0xffffffff

    return state

def length_extend_sha256(original_hash, append_message, original_length):
    # Convert original hash to state
    state = []
    for i in range(0, len(original_hash), 8):
        state.append(int(original_hash[i:i+8], 16))

    # Get padding for original message
    padding = sha256_padding(original_length)
    new_message = padding + append_message

    # Process the new message
    for i in range(0, len(new_message), 64):
        block = new_message[i:i+64]
        if len(block) < 64:
            block = block + b'\x00' * (64 - len(block))
        state = sha256_compress(state, block)

    # Convert state back to hex
    return ''.join('%08x' % s for s in state)

def solve():
    original_hash = "08e7934a4493dd806028a9cfe3b6980375209c58b9895d7ed5b05fd61c02a3f1"
    append_message = b' P.S. I QUIT!'
    original_length = 416  # 32 byte key + 384 byte encrypted message

    extended_hash = length_extend_sha256(original_hash, append_message, original_length)
    print(f"Extended hash: {extended_hash}")

    try:
        conn = remote('crypto.chal.csaw.io', 5050)
        conn.recvuntil(b'?:\n')
        conn.sendline(extended_hash.encode())
        print(conn.recvall(timeout=2).decode())
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    solve()
